1	// ***************************************************************************
2	// ***************************************************************************
3	// Copyright (C) 2017, 2018, 2020, 2022, 2024 Analog Devices, Inc. All rights reserved.
4	// SPDX short identifier: ADIJESD204
5	// ***************************************************************************
6	// ***************************************************************************
7	
8	`timescale 1ns/100ps
9	
10	module jesd204_soft_pcs_rx #(
11	  parameter NUM_LANES = 1,
12	  parameter DATA_PATH_WIDTH = 4,
13	  parameter REGISTER_INPUTS = 0,
14	  parameter INVERT_INPUTS = 0,
15	  parameter IFC_TYPE = 0
16	) (
17	  input clk,
18	  input reset,
19	
20	  input patternalign_en,
21	
22	  input [NUM_LANES*(DATA_PATH_WIDTH*10 + IFC_TYPE*40)-1:0] data,
23	
24	  output reg [NUM_LANES*DATA_PATH_WIDTH*8-1:0] char,
25	  output reg [NUM_LANES*DATA_PATH_WIDTH-1:0] charisk,
26	  output reg [NUM_LANES*DATA_PATH_WIDTH-1:0] notintable,
27	  output reg [NUM_LANES*DATA_PATH_WIDTH-1:0] disperr
28	);
29	
30	  localparam LANE_DATA_WIDTH = DATA_PATH_WIDTH * 10;
31	
32	  wire [NUM_LANES*LANE_DATA_WIDTH-1:0] data_aligned;
33	
34	  wire [NUM_LANES*DATA_PATH_WIDTH*8-1:0] char_s;
35	  wire [NUM_LANES*DATA_PATH_WIDTH-1:0] charisk_s;
36	  wire [NUM_LANES*DATA_PATH_WIDTH-1:0] notintable_s;
37	  wire [NUM_LANES*DATA_PATH_WIDTH-1:0] disperr_s;
38	
39	  reg  [NUM_LANES-1:0] disparity = {NUM_LANES{1'b0}};
40	  wire [DATA_PATH_WIDTH:0] disparity_chain[0:NUM_LANES-1];
41	
42	  wire [NUM_LANES*DATA_PATH_WIDTH*10-1:0] data_s;
43	  wire patternalign_en_s;
44	
45	  always @(posedge clk) begin
46	    char <= char_s;
47	    charisk <= charisk_s;
48	    notintable <= notintable_s;
49	    disperr <= disperr_s;
50	  end
51	
52	  generate
53	    genvar lane;
54	    genvar i;
55	    if (REGISTER_INPUTS > 0) begin
56	      reg                                     patternalign_en_r;
57	      reg [NUM_LANES*DATA_PATH_WIDTH*10-1:0]  data_r;
58	
59	      always @(posedge clk) begin
60	        patternalign_en_r <= patternalign_en;
61	        data_r  <= IFC_TYPE == 0 ? data : {data[59:40],data[19:0]};
62	      end
63	      assign patternalign_en_s = patternalign_en_r;
64	      assign data_s = data_r;
65	    end else begin
66	      assign patternalign_en_s = patternalign_en;
67	      assign data_s = IFC_TYPE == 0 ? data : {data[59:40],data[19:0]};
68	    end
69	
70	    for (lane = 0; lane < NUM_LANES; lane = lane + 1) begin: gen_lane
71	      jesd204_pattern_align #(
72	        .DATA_PATH_WIDTH(DATA_PATH_WIDTH)
73	      ) i_pattern_align (
74	        .clk(clk),
75	        .reset(reset),
76	        .patternalign_en(patternalign_en_s),
77	        .in_data(data_s[LANE_DATA_WIDTH*lane+:LANE_DATA_WIDTH]),
78	        .out_data(data_aligned[LANE_DATA_WIDTH*lane+:LANE_DATA_WIDTH]));
79	
80	      assign disparity_chain[lane][0] = disparity[lane];
81	
